  "the book most books are — one clear story, one steady voice, a structure every reader knows by heart; everything open, everything understood": "الكتاب الذي معظم الكتب — قصة واحدة واضحة، صوت ثابت، بنية يعرفها كل قارئ عن ظهر قلب؛ كل شيء مفتوح، كل مفهوم",
  "the classic shape keeps its form, but undercurrents begin — recurring symbols, quiet foreshadowing, a story that means more than it says": "الشكل الكلاسيكي يحافظ على هيئته، لكن التيارات العميقة تبدأ — رموز متكررة، إشارات خفيفة، قصة تعني أكثر مما تقول",
  "the deepest telling — paragraphs running in several dimensions at once, time folding, the book quietly reading its reader; story, structure and reader scale together": "أعمق الرواية — فقرات تجري في عدة أبعاد في آن واحد، زمن منثور، الكتاب يقرأ قارئه بهدوء؛ القصة، البنية، والقارئ ينمون معاً",
