  "two tellings at once — the tale above and its meaning beneath; echoes and mirrors fold back on earlier pages and reward the second reading": "روايتان في آن واحد — القصة فوق ومدلولها تحتها؛ صدى المرايا يعود إلى صفحات سابقة ويكافئ القراءة الثانية",
  "writing as code — layered registers, riddles and ciphers, each unlock deepening every page before it; the structure itself begins to bend": "الكتابة كرمز — سجلات متعددة الطبقات، ألغاز وشفارات، كل فك يعمق كل صفحة قبله؛ البنية نفسها تبدأ في الانحناء",
