  "Tell me about the profession of \"{name}\" in the astral domains — what does this work involve, and how does it serve evolution?": "حدثني عن مهنة \"{name}\" في الممالك الأثيرية — ما طبيعة هذا العمل، وكيف يخدم التطور؟",
  "Tenure": "المدة",
  "The field received your question but could not complete the transmission.": "لقد استقبل الحقل سؤالك ولكنه لم يتمكن من إتمام الإرسال.",
  "The Mirror Is Listening": "المرآة تستمع",
  "The voice field is momentarily quiet.": "حقل الصوت هادئ مؤقتاً.",
  "This channel is quiet.": "هذا القنوات هادئة.",
  "This dossier reflects channeled tradition and worldbuilding within the Mirror archive. It is offered for reflection and wonder — not as established science.": "يُعكس هذا الملف التقليد المنقَّل وبناء العالم داخل أرشيف المرآة. يُقدَّم للتأمل والدهشة — وليس كعلم مُؤسَّس.",
