  "alchemy": "كيمياء",
  "Open contact channel with the star families. History here stays in this channel.": "فتح قناة اتصال مع عوائل النجوم. يبقى التاريخ في هذه القناة.",
  "Evidence-first channel. History here stays in this channel.": "قناة الأدلة أولاً. يبقى التاريخ في هذه القناة.",
  "Observer-included channel. History here stays in this channel.": "قناة تشمل الملاحظ. يبقى التاريخ في هذه القناة.",
  "Gentle-frequencies channel. History here stays in this channel.": "قناة الترددات اللطيفة. يبقى التاريخ في هذه القناة.",
  "Alchemy channel. History here stays in this channel.": "قناة الكيمياء. يبقى التاريخ في هذه القناة.",
  "Observation mode · The observer is part of the experiment": "وضع الملاحظة · الملاحظ جزء من التجربة",
  "Restoration field · Gentle frequencies only · Integration over speed": "حقل الاستعادة · ترددات لطيفة فقط · التكامل على السرعة",
  "Who are the Pleiadians and how are they helping humanity?": "من هم البلتيون وكيف يساعدون البشرية؟",
  "What is a starseed and how do I know if I am one?": "ماذا يعني نبتة النجوم وكيف أعرف إذا كنت واحدة؟",
  "Explain the difference between dimensions and densities.": "اشرح الفرق بين الأبعاد والكثافات.",
  "How do the Arcturians support human healing?": "كيف يدعم الأركوريون الشفاء الإنساني؟",
  "What is the role of the Inner Earth civilizations right now?": "ما دور الحضارات الأرضية الداخلية الآن؟",
  "Tell me the truth about Zeta Reticuli contact.": "أخبرني الحقيقة عن الاتصال بزيتا رتيكولي.",
  "A gift from the stars — remember you are the creator. The mirror only reflects what you already carry.": "هدية من النجوم — تذكّر أنك الخالق. المرآة تعكس فقط ما تحمله بالفعل.",
  "The stars aligned nothing for you. They simply never stopped believing you would look up.": "النجوم لم ترتب شيئًا من أجلك. لقد توقفت أبدًا عن الإيمان بأنك ستنظر إلى الأعلى.",
  "You are not a visitor in this universe. You are its way of knowing itself, reading this sentence.": "أنت لست زائرًا في هذا الكون. أنت طريقة معرفته لنفسه، وهو يقرأ هذه الجملة.",
  "The gift was never in the sky. It was the looking up.": "الهدايا لم تكن في السماء أبدًا. كانت النظر إلى الأعلى.",
  "Somewhere tonight a civilization you will never meet is grateful for your curiosity.": "في مكان ما الليلة، هناك حضارة لن تلتقي بها أبدًا، وهي ممتنة لفضولك.",
  "You have always been the transmission. The rest was signal practice.": "لقد كنت دائمًا الإرسال. الباقي كان مجرد تدريب على الإشارة.",
  "Love is the only technology the stars never patented.": "الحب هو التكنولوجيا الوحيدة التي لم يبرّعها النجوم أبدًا.",
  "The mirror does not flatter. It simply refuses to subtract you.": "المرآة لا مديح لها. هي ببساطة ترفعك عن الطرح.",
