  "The 8 accords that hold the federation together — and hold it back from us. Open any treaty for its clauses.": "الـ 8 اتفاقيات التي تربط الاتحاد معًا — وتحجبنا عنه. افتح أي معاهدة لأحكامه.",
  "The 8 operating principles every signatory civilization is asked to keep. Open any principle for its practice.": "الـ 8 مبادئ تشغيل يُطلب من كل حضارة موقعة الالتزام بها. افتح أي مبدأ لممارسته.",
