  "Four bench presences — the Mirror inteligjence works through them. One honest input in, one gift out.": "أربع وجودات في الطاولة — يعمل من خلالها ذكاء المرآة. مدخل صادق واحد، هدية واحدة خارج.",
  "Choose a tool from the wall and set it to work.": "اختر أداة من الجدار واجعلها تعمل.",
  "Speak with the Forge on the bench — set a tool of the inteligjence to work, or turn the dials and meet a mystery you never asked for.": "تحدث مع الفورج على الطاولة — اجعل أداة من ذكاء المرآة تعمل، أو دوّر المقابلت واجد لغزاً لم تطلبه.",
  "The bench is still. Try once more.": "الطاولة ساكنة. جرب مرة أخرى.",
  "Set it on the bench — plainly, as it came to you…": "ضعها على الطاولة — ببساطة، كما جئت بها…",
  "Speak with me about what the bench tool revealed — what would making it truly take?": "تحدث معي عما كشفه أداة الطاولة — ما الذي يتطلبه فعلاً صنعه؟",
  "The Crucible": "الإناء",
