  "The Name-Giver": "من يسمي",
  "Describe what you are making — receive the name it was always waiting for, and a second name beside it.": "صف ما تصنعه — استقبل الاسم الذي كان ينتظره دائماً، واسم ثانٍ بجانبه.",
  "Ask for the name": "اطلب الاسم",
