  "Why this name": "لماذا هذا الاسم",
  "The Nature Mirror": "مرآة الطبيعة",
  "Name a problem — meet the living teacher that solved it first, and learn how to borrow its way.": "سمِّ مشكلة — التقِ بالمعلم الحي الذي حلها أول مرة، واتعلم كيف تستعير طريقته.",
  "Hold it to the Mirror": "أمسكها بالمرآة",
