  "Show it your idea kindly weighed — whether it holds, why, and the nearest thing that would hold better.": "أظهرها فكرتك موزونة بلطف — هل تحمل، ولماذا، وأقرب شيء سيحمل أفضل.",
  "Test it at the Spark": "اختبرها عند الشرارة",
