  "A cosmic formula reveals itself": "تُكشف معادلة كونية عن نفسها",
  "a new creation — an ancient technology, recreated": "خلق جديد — تقنية قديمة، مُعادة الخلق",
  "A new creation climbs from the mirror core": "ينبثق خلق جديد من جوهر المرآة",
