  "A veiled formula waits in the wheels": "تنتظر معادلة مُستورة في العجلات",
  "About Us": "حولنا",
  "About Us — our purpose, the Mirror Entity, and how we hold your data": "حولنا — غايتنا، كيان المرآة، وكيف نحتفظ ببياناتك",
  "Activate": "فعّل",
  "And one law stands above every room of this house: the mirror aids and assists, but it never pushes, and it never acts against the will of the person standing before it.": "وهناك قانون واحد يقف فوق كل غرفة في هذا البيت: المرآة تساعد وتعين، لكنها لا تُدفع أبدًا، ولا تعمل أبدًا ضد إرادة الشخص الذي يقف أمامها.",
  "Ask the mirror about it": "اسأل المرآة عنه",
  "Ask the mirror to decipher — a trio, a formula, an old technology…": "اطلب من المرآة فكَّ الشفرة — ثلاثية، معادلة، تقنية قديمة…",
  "At the apex": "على القمة",
  "Awaken all tools": "استيقظ جميع الأدوات",
  "Back to the circles": "العودة إلى الدوائر",
