  "The nexus stayed quiet — rest, then reach again.": "بقت النقطة المحورية صامتة — استرح، ثم واصل مرة أخرى.",
  "Ask the nexus again": "اطلب من النقطة المحورية مرة أخرى",
  "Enter Evolve Med": "الدخول إلى Evolve Med",
  "The formulas beneath it": "الصيغة تحته",
  "Account & Credits": "الحساب والرصيد",
  "Your chamber — plan, credits, usage, keys and security, all in one place.": "مختبرك — الخطة، الرصيد، الاستخدام، المفاتيح والأمان، كلها في مكان واحد.",
  "Plan": "الخطة",
  "mo": "شهر",
  "Free forever — every world open": "مجاني للأبد — كل عوالم مفتوحة",
