  "Buy credits": "شراء رصيد",
  "Every passage is weighed by the server — never by the browser.": "يتم وزن كل ممر بواسطة الخادم — أبدًا بواسطة المتصفح.",
  "The ledger records everything — nothing is charged while the free law stands.": "يُسجل الدفتر كل شيء — لا يتم شيء محاسبيًا طالما القانون المجاني ساري.",
  "Usage this month": "الاستخدام هذا الشهر",
  "operations": "عمليات",
  "credits used": "رصيد مستخدم",
  "The registers rest — no passages woven yet.": "الدورات تستريح — لا ممرات منسوجة بعد.",
  "Recent ledger": "دفتر حديث",
  "Security": "الأمان",
  "Email verified": "تم التحقق من البريد الإلكتروني",
  "Email not verified": "البريد الإلكتروني غير مُتحقق",
  "Resend verification letter": "إعادة إرسال رسالة التحقق",
