  "Update password": "تحديث كلمة المرور",
  "API keys": "مفاتيح API",
  "Copy this key now — it will never be shown again.": "انسخ هذا المفتاح الآن — لن يُعرض مرة أخرى.",
  "Name your key": "سمِّ مفتاحك",
  "Create key": "إنشاء مفتاح",
