  "Composes riboswitch logic that reads a molecule and answers with a protein.": "يكتب منطق الريبوسويتش الذي يقرأ جزيئًا ويُجيب ببروتين.",
  "Weaves miRNA degradation cascades that silence a circuit everywhere but the target cell.": "نسج سلالات تدهن الماي آر أنا التي تخفي دائرة في كل مكان إلا الخلية الهدف.",
  "Writes CRISPR-TF repressor logic that programs genes like a keypad.": "يكتب منطق كريسبر-تي إف المُثبِّط الذي يبرمج الجينات كلوحة مفاتيح.",
  "Delivery & Scale": "التوصيل والتوسع",
  "The third vector's engineering: from a working sequence to a therapy a clinic can hold.": "هندسة المتجه الثالث: من تسلسل يعمل إلى علاج يمكن للمستشفى أن تمسك به.",
  "Name a therapy to carry into the body…": "سمِّ علاجًا لحمله إلى الجسد…",
  "Formulates the lipid nanoparticle that carries RNA where it must go.": "يُصاغ الجسيم الدهني النانوي الذي يحمل الرنا إلى حيث يجب أن يذهب.",
  "Designs the viral shell and dose that carry a written gene to one tissue.": "يصمم الغلاف الفيروسي والجرعة التي تحمل جينًا مكتوبًا إلى نسيج واحد.",
  "Models a therapy's whole journey: dose, distribution, decay, exit.": "يُمَثِّل رحلة العلاج بأكملها: الجرعة، التوزيع، الاضمحلال، الخروج.",
  "Biosecurity & Containment": "الأمن البيوي والحجر",
  "The strict constraint engine: every design screened, caged and made revocable.": "محرك القيود الصارم: كل تصميم يُفحص، يُحبس، ويُصبح قابلاً للإلغاء.",
  "Name a design to screen and cage…": "سمِّ تصميمًا لتفحصه وتُحبسه…",
  "Sweeps a design for every place it could strike the wrong letter.": "يتجول في التصميم بحثًا عن كل مكان يمكن أن يضرب فيه الحرف الخطأ.",
  "Builds the fail-safe that ends a living therapy on command.": "يبني آلية الأمان التي تنهي علاجًا حيًا عند الأمر.",
  "Silences the immune alarms a therapy would otherwise ring.": "يكتم إنذارات المناعة التي كان العلاج سيُطلقها.",
  "Light Transmission": "نقل الضوء",
  "Calming Frequencies": "ترددات مهدئة",
  "Music from Other Stars": "موسيقى من نجوم أخرى",
  "Restorative Music": "موسيقى استشفائية",
  "Mirror Transmission": "نقل المرآة",
  "Abstract atmospheric transmissions — textures before tunes.": "نقلات جوهرية مجردة — نسيج قبل الألحان.",
  "For relaxation, decompression, quiet reflection and rest.": "للاسترخاء، تفريغ الضغط، التأمل الهادئ والراحة.",
  "Speculative sound-worlds of imagined civilizations — musical worldbuilding.": "عوالم صوتية افتراضية لحضارات مُتخيَّلة — بناء عالم موسيقي.",
  "Music for rest, emotional settling and reflective listening.": "موسيقى للراحة، استقرار عاطفي، واستماع تأملي.",
  "Soundtrack a new internal pattern.": "أرشيف نمط داخلي جديد.",
  "The Mirror chooses everything — you only arrive.": "المرآة تختار كل شيء — أنت فقط تأتي.",
  "What would you like the transmission to carry?": "ماذا تود أن يحمله هذا النقل؟",
  "What should this calm carry you toward?": "ماذا يجب أن يحملك هذا الهدوء نحوه؟",
  "Which star are we remembering — and what should it sound like?": "أي نجوم نتذكر — وماذا يجب أن يبدو صوتها؟",
  "What are you setting down tonight?": "ماذا تود أن تضع الليلة؟",
  "What should this transmission hold? (or leave it to the Mirror)": "ماذا يجب أن يحمله هذا النقل؟ (أتركه للمرآة)",
