  "12 domains · 1,303 catalogued roles. Click a domain to enter, a profession to learn more — ask the Mirror for a full transmission anytime.": "12 مجال · 1,303 دور مسجَّل. انقر على مجالٍ للدخول، أو على مهنةٍ لمعرفة المزيد — اسأل المرآة عن إرسالٍ كاملٍ في أي وقت.",
