  "Interdimensional Archive ({n})": "الأرشيف بين الأبعاد ({n})",
  "Codex Exobiologica": "كودكس الإكسيوبولوجيكا",
  "History of your works": "تاريخ أعمالك",
  "Everything your tools have made and kept on this device — a closed tab never takes a work away. One touch resumes it exactly where it stood.": "كل ما صنعته أدواتك وحفظتها على هذا الجهاز — علامة تبويب مغلقة لا تأخذ عملًا بعيدًا. لمسة واحدة تستأنفه بالضبط حيث كان.",
  "Nothing rests here yet — every conversation, every book, every code you make keeps itself here automatically.": "لا شيء يرقد هنا بعد بعد — كل محادثة، كل كتاب، كل كود تصنعه يحفظ نفسه هنا تلقائيًا.",
  "Resume": "استئناف",
